# Check if columns exist and operation is valid
if 'Awards_Nominated' not in df.columns:
    print(f"❌ Error: Column 'Awards_Nominated' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif 'Group' not in df.columns:
    print(f"❌ Error: Group by column 'Group' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif "count" not in ['count', 'sum', 'avg', 'min', 'max']:
    print(f"❌ Error: Invalid operation 'count'. Valid operations: ['count', 'sum', 'avg', 'min', 'max']")
else:
    try:
        if "count" == "count":
            result = df.groupby('Group')['Awards_Nominated'].count()
        elif "count" == "sum":
            result = df.groupby('Group')['Awards_Nominated'].sum()
        elif "count" == "avg":
            result = df.groupby('Group')['Awards_Nominated'].mean()
        elif "count" == "min":
            result = df.groupby('Group')['Awards_Nominated'].min()
        elif "count" == "max":
            result = df.groupby('Group')['Awards_Nominated'].max()

        print(f"✅ Count of 'Awards_Nominated' by 'Group':")
        print(result)

        # Convert to dataframe for consistency
        result_df = result.reset_index()
        result_df.columns = ['Group', f'count_result']
        print(f"\n🔍 Result as table:")
        print(result_df)

    except Exception as e:
        print(f"❌ Error computing grouped count: {e}")
        print(f"Column dtypes: {df[['Awards_Nominated', 'Group']].dtypes}")

